"""Income applications of the synthetic borrowers in income-engine/data, for the console demo."""

from dataclasses import dataclass
from decimal import Decimal
from pathlib import Path

import pandas as pd

from collateral_engine.income import (
    AccountTransaction,
    EmploymentType,
    IncomeApplication,
    IncomeAssessmentRequest,
)

# The income engine's synthetic borrowers are generated by archetype.
EMPLOYMENT_BY_ARCHETYPE = {
    "salaried_tbilisi": EmploymentType.SALARIED,
    "young_first_loan": EmploymentType.SALARIED_YOUNG,
    "farmer_kakheti": EmploymentType.FARMER,
    "self_employed": EmploymentType.SELF_EMPLOYED,
    "remittance_hh": EmploymentType.REMITTANCE,
}


class IncomeDemoDataError(ValueError):
    """The synthetic income data is missing or has no such borrower."""


@dataclass(frozen=True)
class IncomeDemoBorrower:
    borrower_id: int
    description_en: str
    description_ka: str


INCOME_DEMO_BORROWERS = (
    IncomeDemoBorrower(
        747,
        "Giorgi: vineyard owner in Kakheti, no credit history",
        "გიორგი: ვენახის მფლობელი კახეთში, საკრედიტო ისტორიის გარეშე",
    ),
    IncomeDemoBorrower(
        122,
        "Levan: income inflated by circular transfers",
        "ლევანი: შემოსავალი გაბერილია წრიული გადარიცხვებით",
    ),
)


def load_income_demo_request(data_dir: Path, borrower_id: int) -> IncomeAssessmentRequest:
    borrowers_path = data_dir / "borrowers.csv"
    transactions_path = data_dir / "transactions.parquet"
    if not borrowers_path.exists() or not transactions_path.exists():
        raise IncomeDemoDataError(
            f"{data_dir} has no synthetic income data; run 'make all' in income-engine/"
        )
    borrowers = pd.read_csv(borrowers_path).set_index("borrower_id")
    if borrower_id not in borrowers.index:
        raise IncomeDemoDataError(f"borrower {borrower_id} is not in {borrowers_path}")
    transactions = pd.read_parquet(transactions_path)
    own_transactions = transactions[transactions["borrower_id"] == borrower_id]
    return IncomeAssessmentRequest(
        application=_application(borrower_id, borrowers.loc[borrower_id]),
        transactions=[_transaction(row) for row in own_transactions.itertuples()],
    )


def _application(borrower_id: int, borrower: pd.Series) -> IncomeApplication:
    bureau_score = None if pd.isna(borrower["bureau_score"]) else float(borrower["bureau_score"])
    return IncomeApplication(
        borrower_id=borrower_id,
        application_date=borrower["application_date"],
        employment_type=EMPLOYMENT_BY_ARCHETYPE[borrower["archetype"]],
        declared_income_gel=_gel(borrower["declared_income_gel"]),
        existing_debt_payment_declared_gel=_gel(borrower["existing_debt_payment_declared"]),
        income_currency=borrower["income_currency"],
        loan_amount_gel=_gel(borrower["loan_amount_gel"]),
        loan_currency=borrower["loan_currency"],
        term_months=int(borrower["term_months"]),
        annual_rate=Decimal(str(borrower["annual_rate"])),
        bureau_score=bureau_score,
        consent_id=f"OB-DEMO-{borrower_id}",
    )


def _transaction(row: object) -> AccountTransaction:
    return AccountTransaction(
        tx_id=int(row.tx_id),
        date=pd.Timestamp(row.date).date(),
        amount=Decimal(str(row.amount)),
        currency=row.currency,
        counterparty=row.counterparty,
        description=row.description,
    )


def _gel(amount: float) -> Decimal:
    return Decimal(str(amount)).quantize(Decimal("0.01"))
